(async function(){
    (async function(){ for (let i=0;i<50;i++){ if (document.readyState==='complete' && document.body) break; await new Promise(r=>setTimeout(r,2000)); } await new Promise(r=>setTimeout(r,3000)); return document.readyState; })()
    location.href='https://sp.194964.com/sns/snstype/show_mutual_list.html';
    for (let i=0;i<30;i++){ await new Promise(r=>setTimeout(r,2000)); if (document.readyState==='complete' && document.querySelectorAll('.type--list').length>0) break; }
    await new Promise(r=>setTimeout(r,3000));
    const out = { href: location.href, cards: document.querySelectorAll('.type--list').length };
    var card1 = document.querySelector('.type--list');
    if (card1) {
      out.nameEl = card1.querySelector('.type-list-name') ? card1.querySelector('.type-list-name').textContent.trim() : null;
      out.ageEl = card1.querySelector('.type-list-age') ? card1.querySelector('.type-list-age').textContent.trim().replace(/\s+/g,' ') : null;
      out.regionEl = card1.querySelector('.type-list-region') ? card1.querySelector('.type-list-region').textContent.trim() : null;
      out.memberId = card1.querySelector('input[name="targetSnsMemberId[]"]') ? card1.querySelector('input[name="targetSnsMemberId[]"]').value : null;
      out.interestIcons = Array.from(card1.querySelectorAll('img.affinity_img_icon, img[src*="leisure"]')).map(function(i){ return String(i.src||''); });
      var pl = card1.querySelector('a[type-list-link]') || card1.querySelector('a[href*="show_profile"]');
      out.profileLink = pl ? pl.getAttribute('href') : null;
      out.cardText = String(card1.textContent||'').trim().replace(/\s+/g,' ').slice(0, 300);
    }
    return JSON.stringify(out);
  })()
